/* wl_hs.c and wl_frame.c, unchanged, on the real cipher (wl_crypto_mbedtls.c
 * over mbedTLS 3.6's own sources), against what pc/wifi_session.py produces:
 * a handshake and a discovery exchange byte for byte, the PC's frames
 * opening on the board, and the board's frames sealing to the PC's bytes in
 * every type and at the widest sizes. The two halves of the wire were each
 * tested alone; this is where they are held to each other. vectors.h is
 * generated by tools/gen_wire_vectors.py. Built by check_host_tests.sh with
 * wl_crypto_real's mbedTLS arguments.
 */
#include <stdio.h>
#include <string.h>

#include "wl_crypto.h"
#include "wl_frame.h"
#include "wl_hs.h"
#include "tests/wl_wire_real/vectors.h"

static int fails;
static void check(int ok, const char *name)
{
	if (!ok) {
		fails++;
		printf("FAIL %s\n", name);
	} else {
		printf("PASS %s\n", name);
	}
}

/* wl_random's source: Nb is 0x5a throughout, as the generator assumes. */
int sys_csrand_get(void *dst, size_t len)
{
	memset(dst, 0x5a, len);
	return 0;
}

int main(void)
{
	struct wl_hs hs;
	struct wl_dir rx, tx;
	uint8_t m1[WL_M1_LEN], m3[WL_M3_LEN], kpb[32], kbp[32], a[WL_A_LEN];
	uint8_t frame[WL_FRAME_MAX], body[WL_PT_MAX], type;
	int ok_open = 1, ok_seal = 1;

	check(wl_hs_m1(&hs, m1) == 0 && memcmp(m1, wlw_m1, sizeof(m1)) == 0,
	      "m1_matches_pc");
	/* The PC's M2 is the daemon's reply to exactly this Nb. */
	check(wl_hs_check_m2(&hs, wlw_key, wlw_m2, sizeof(wlw_m2)) == 0 &&
		      memcmp(hs.np, wlw_np, 16) == 0,
	      "pc_m2_accepted");
	check(wl_hs_m3(&hs, wlw_key, m3) == 0 &&
		      memcmp(m3, wlw_m3, sizeof(m3)) == 0,
	      "m3_matches_pc");
	check(wl_hs_keys(&hs, wlw_key, kpb, kbp) == 0 &&
		      memcmp(kpb, wlw_k_pb, 32) == 0 &&
		      memcmp(kbp, wlw_k_bp, 32) == 0,
	      "session_keys_match_pc");

	check(wl_disc_answer(wlw_key, wlw_q, sizeof(wlw_q), WLW_PORT, a) ==
		      WL_A_LEN &&
		      memcmp(a, wlw_a, sizeof(a)) == 0,
	      "discovery_answer_matches_pc");

	memset(&rx, 0, sizeof(rx));
	memset(&tx, 0, sizeof(tx));
	memcpy(rx.key, kpb, 32);	/* the board reads what the PC sends */
	memcpy(tx.key, kbp, 32);
	for (int i = 0; i < WLW_NFRAMES; i++) {
		const struct wlw_frame *f = &wlw_frames[i];
		int fl;

		if (wl_frame_len(f->to_board) != 1 + f->body_len ||
		    wl_frame_open(&rx, f->to_board, f->frame_len, &type, body,
				  sizeof(body)) != f->body_len ||
		    type != (uint8_t)f->type ||
		    memcmp(body, f->body, f->body_len) != 0) {
			ok_open = 0;
		}
		fl = wl_frame_seal(&tx, (uint8_t)f->type, f->body, f->body_len,
				   frame, sizeof(frame));
		if (fl != f->frame_len ||
		    memcmp(frame, f->to_pc, f->frame_len) != 0) {
			ok_seal = 0;
		}
	}
	check(ok_open, "pc_frames_open_on_board");
	check(ok_seal, "board_frames_seal_to_pc_bytes");
	return fails ? 1 : 0;
}
